looks_like_encoded_secret(value) {
    value.ir_type == "String"
    regex.match("^[A-Za-z0-9+/]{15,}={0,2}$", value.value)
}

looks_like_hash(value) {
    value.ir_type == "String"
    regex.match("^\\$[0-9a-zA-Z]+\\$", value.value)
}

